package ktanesolver.module.modded.regular.cruel_countdown;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.countdown.*;
class CruelCountdownSolverTest{private final CruelCountdownSolver solver=new CruelCountdownSolver();
	@Test void reusesLegalCountdownArithmeticForCruelNumbers(){CountdownOutput out=solve(new CountdownInput(160,List.of(90,70,50,30,15,14)));assertThat(out.operations()).containsExactly(new CountdownOutput.Operation(90,"+",70,160));}
	@Test void acceptsOneLargeNumberAndRepeatedSmallNumbers(){CountdownOutput out=solve(new CountdownInput(100,List.of(90,15,15,5,2,1)));assertThat(out.operations()).isNotEmpty();assertThat(out.operations().getLast().result()).isEqualTo(100);}
	@Test void rejectsImpossibleGeneratorValuesAndBands(){assertFailure(List.of(100,70,50,30,15,14));assertFailure(List.of(90,80,50,30,15,14));assertFailure(List.of(15,14,13,12,11,10));assertFailure(List.of(90,70,50,50,15,14));}
	private void assertFailure(List<Integer>numbers){assertThat(solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new CountdownInput(160,numbers))).isInstanceOf(SolveFailure.class);}@SuppressWarnings("unchecked")private CountdownOutput solve(CountdownInput input){return((SolveSuccess<CountdownOutput>)solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),input)).output();}}
